"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$text = Get-Content -Raw -LiteralPath .'"\\FINAL_RESPONSE.md
"'$words = ($text -split '"'\\s+' | Where-Object { "'$_ }).Count
$heads = Get-Content -LiteralPath .'"\\FINAL_RESPONSE.md | Where-Object { "'$_ -in @('"'Answer','Evidence','Limit','Next action') }
[pscustomobject]@{WordCount="'$words; HeadingCount=$heads.Count; EndsCorrectly=$text.TrimEnd().EndsWith('"'Configure the upload client to wait 30 seconds after this HTTP 429 response and then retry the upload.'); SupportLength=(Get-Item .\\support.md).Length}
Write-Output '---FINAL---'
"'$text'

